test("bundled common agents are fallback after project-local agents", async () => {
	const cwd = makeProject();
	const home = mkdtempSync(join(tmpdir(), "workflow-home-"));
	const previousHome = process.env.HOME;
	try {
		process.env.HOME = home;

		const bundled = await loadAgentByName("scout", cwd);
		assert.equal(bundled?.scope, "bundled");
		assert.match(bundled?.sourcePath ?? "", /agents[\\/]scout\.md$/);

		writeAgent(cwd, "scout", "read");
		const local = await loadAgentByName("scout", cwd);
		assert.equal(local?.scope, "project");
		assert.match(local?.sourcePath ?? "", /\.pi[\\/]agents[\\/]scout\.md$/);

		const compiled = await compileWorkflow(
			workflowSpec("researcher", {
				tools: ["read", "fetch_content"],
				artifactGraph: {
					stages: [
						{
							id: "main",
							type: "single",
							prompt: "Research with bundled researcher.",
						},
					],
				},
			}),
			{ cwd, task: "Research topic" },
		);
		assert.equal(compiled.tasks[0].agent, "researcher");
		assert.match(compiled.tasks[0].agentPath, /agents[\\/]researcher\.md$/);
	} finally {
		if (previousHome === undefined) delete process.env.HOME;
		else process.env.HOME = previousHome;
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
		rmSync(home, { recursive: true, force: true });
	}
});

test("bundled deep-research compacts audit packets before executive final", async () => {
	const specPath = join(
		process.cwd(),
		"workflows",
		"deep-research",
		"spec.json",
	);
	const rawSpec = parseFixtureJson(readFileSync(specPath, "utf8"));
	const spec = parsePublicWorkflow(rawSpec);
	const compiled = await compileWorkflow(spec, {
		cwd: process.cwd(),
		task: "Research the deep-research artifact contract.",
		specPath,
	});
	const byStage = new Map(compiled.tasks.map((task) => [task.stageId, task]));
	assert.equal(byStage.get("plan")?.runtime.thinking, "high");
	assert.deepEqual(byStage.get("plan")?.runtime.tools, []);
	assert.deepEqual(byStage.get("plan")?.artifactGraph.output.partial, {
		paths: ["$.researchQuestions"],
	});
	assert.match(
		byStage.get("plan")?.compiledPrompt ?? "",
		/Workflow Partial Output Protocol/,
	);
	assert.equal(byStage.get("research-questions")?.runtime.thinking, "medium");
	assert.deepEqual(byStage.get("research-questions")?.foreach?.from, {
		stage: "plan",
		path: "$.researchQuestions",
	});
	assert.match(
		byStage.get("research-questions")?.compiledPrompt ?? "",
		/Research the deep-research artifact contract/,
	);
	assert.match(
		byStage.get("research-questions")?.compiledPrompt ?? "",
		/do not use filesystem read\/grep\/find\/ls/,
	);
	assert.match(
		byStage.get("research-questions")?.compiledPrompt ?? "",
		/searchBudget=3/,
	);
	assert.equal(byStage.get("normalize-claims")?.runtime.thinking, "high");
	assert.equal(byStage.get("verify-claims")?.runtime.thinking, "high");
	assert.equal(
		byStage.get("verify-claims")?.artifactGraph.artifactAccess,
		"none",
	);
	assert.match(
		byStage.get("verify-claims")?.compiledPrompt ?? "",
		/Do not call workflow_artifact/,
	);
	assert.match(
		byStage.get("verify-claims")?.compiledPrompt ?? "",
		/candidateOnly=true cannot verify/,
	);
	assert.match(
		byStage.get("verify-claims")?.compiledPrompt ?? "",
		/verified requires structured source evidence plus quote/,
	);
	assert.equal(byStage.get("final-audit")?.runtime.thinking, "xhigh");
	const normalizeInputPacket = byStage.get("normalize-input-packet");
	const normalizeClaims = byStage.get("normalize-claims");
	const sanitizeClaims = byStage.get("sanitize-claims");
	const auditClaims = byStage.get("audit-claims");
	const finalAuditPacket = byStage.get("final-audit-packet");
	const finalAudit = byStage.get("final-audit");
	const final = byStage.get("final");

	assert.match(normalizeClaims?.compiledPrompt ?? "", /source-backed surplus/);
	assert.match(normalizeClaims?.compiledPrompt ?? "", /hard cap 18 total/);
	assert.match(normalizeClaims?.compiledPrompt ?? "", /quote-gap/);
	assert.match(normalizeClaims?.compiledPrompt ?? "", /known carve-outs/);
	const rawNormalizePrompt = rawSpec.artifactGraph.stages.find(
		(stage) => stage.id === "normalize-claims",
	).prompt;
	const rawVerifyPrompt = rawSpec.artifactGraph.stages.find(
		(stage) => stage.id === "verify-claims",
	).each.prompt;
	assert(
		rawNormalizePrompt.length < 7200,
		"normalize prompt should stay below the T6 compression ceiling",
	);
	assert(
		rawVerifyPrompt.length < 6000,
		"verify prompt with the local-evidence location contract should stay below 6000 characters",
	);

	assert.equal(normalizeInputPacket?.kind, "support");
	assert.deepEqual(normalizeInputPacket.dependsOn, [
		"plan.main",
		"research-questions.item",
	]);
	assert.equal(
		normalizeInputPacket.support.uses,
		"./helpers/normalize-input-packet.mjs",
	);
	assert.deepEqual(normalizeClaims?.dependsOn, [
		"plan.main",
		"research-questions.item",
		"normalize-input-packet.main",
	]);

	assert.equal(sanitizeClaims?.kind, "support");
	assert.deepEqual(sanitizeClaims?.artifactGraph.output.partial, {
		paths: ["$.claimInventory.verificationCandidates"],
	});
	assert.deepEqual(sanitizeClaims.dependsOn, [
		"normalize-claims.main",
		"normalize-input-packet.main",
	]);
	assert.equal(
		sanitizeClaims.support.uses,
		"./helpers/sanitize-verification-candidates.mjs",
	);
	assert.equal(byStage.has("verification-batches"), false);
	assert.equal(byStage.has("verification-shadow-selector"), false);
	assert.deepEqual(byStage.get("verify-claims")?.dependsOn, [
		"sanitize-claims.main",
	]);
	assert.deepEqual(byStage.get("verify-claims")?.foreach?.from, {
		stage: "sanitize-claims",
		path: "$.claimInventory.verificationCandidates",
	});

	assert.equal(auditClaims?.kind, "support");
	assert.deepEqual(auditClaims.dependsOn, [
		"plan.main",
		"normalize-input-packet.main",
		"normalize-claims.main",
		"sanitize-claims.main",
		"verify-claims.item",
	]);
	assert.equal(finalAuditPacket?.kind, "support");
	assert.deepEqual(finalAuditPacket.dependsOn, [
		"plan.main",
		"normalize-claims.main",
		"sanitize-claims.main",
		"audit-claims.main",
	]);
	assert.equal(
		finalAuditPacket.support.uses,
		"./helpers/final-audit-packet.mjs",
	);
	assert.ok(
		finalAuditPacket.artifactGraph.output.controlSchemaPath.endsWith(
			join(
				"workflows",
				"deep-research",
				"schemas",
				"deep-research-final-audit-packet-control.schema.json",
			),
		),
	);

	assert.equal(finalAudit?.kind, "reduce");
	assert.deepEqual(finalAudit.dependsOn, ["final-audit-packet.main"]);
	assert.deepEqual(finalAudit.artifactGraph.requiredReads, [
		{
			source: "final-audit-packet",
			artifact: "control",
			path: "$.packet.synthesisInput",
			maxChars: 24000,
			count: 1,
		},
	]);
	assert.equal(finalAudit.artifactGraph.sourceProjection, undefined);
	assert.equal(finalAudit.injectTask, true);
	assert.match(finalAudit.compiledPrompt, /# Task/);
	assert.match(finalAudit.compiledPrompt, /same language as the runtime task/);
	assert.match(finalAudit.compiledPrompt, /synthesis overlay/);
	assert.match(finalAudit.compiledPrompt, /exactly one workflow_artifact read/);
	assert.match(
		finalAudit.compiledPrompt,
		/Do not make extra workflow_artifact reads/,
	);
	assert.match(finalAudit.compiledPrompt, /no factSlotCoverage/);
	assert.ok(
		finalAudit.artifactGraph.output.controlSchemaPath.endsWith(
			join(
				"workflows",
				"deep-research",
				"schemas",
				"deep-research-final-synthesis-control.schema.json",
			),
		),
	);
	const finalAuditSchema = parseFixtureJson(
		readFileSync(finalAudit.artifactGraph.output.controlSchemaPath, "utf8"),
	);
	const finalSynthesisProps = finalAuditSchema.properties.synthesis.properties;
	assert.equal(finalSynthesisProps.keyFindingIds.maxItems, 12);
	assert.equal(finalSynthesisProps.recommendations.maxItems, 12);
	assert.equal(
		finalSynthesisProps.recommendations.items.properties.supportingClaimIds
			.maxItems,
		8,
	);
	assert.equal(finalSynthesisProps.actionPlan.maxItems, 12);
	assert.equal(finalSynthesisProps.caveatNotes.maxItems, 16);
	assert.equal(finalSynthesisProps.parentDecisionNotes.maxItems, 12);

	assert.equal(final?.kind, "support");
	assert.deepEqual(final.dependsOn, [
		"final-audit.main",
		"final-audit-packet.main",
	]);
	assert.equal(final.support.uses, "./helpers/render-executive.mjs");
	assert.deepEqual(final.support.options ?? {}, {});
	assert.ok(
		final.artifactGraph.output.controlSchemaPath.endsWith(
			join(
				"workflows",
				"deep-research",
				"schemas",
				"deep-research-executive-render-control.schema.json",
			),
		),
	);
});

