test("deep-research verification tier planner enforces sanitize schema caps", async () => {
	const helperPath = join(
		dirname(fileURLToPath(import.meta.url)),
		"..",
		"..",
		"workflows",
		"deep-research",
		"helpers",
		"tier-verification-candidates.mjs",
	);
	const helper = (
		await import(`${pathToFileURL(helperPath).href}?test=${Date.now()}`)
	).default;
	const sanitizeSchema = parseFixtureJson(
		readFileSync(
			join(
				process.cwd(),
				"workflows",
				"deep-research",
				"schemas",
				"deep-research-sanitize-claims-control.schema.json",
			),
			"utf8",
		),
	);
	const schemaCap =
		sanitizeSchema.properties.claimInventory.properties.verificationCandidates
			.maxItems;
	assert.equal(schemaCap, 48);

	const overflow = Array.from({ length: schemaCap + 2 }, (_, index) => ({
		id: `claim-${String(index + 1).padStart(3, "0")}`,
		claim: `Claim ${index + 1}.`,
	}));
	const out = await helper({
		sources: {
			"sanitize-claims.main": {
				claimInventory: { verificationCandidates: overflow },
			},
		},
		options: { coreTierSize: 999 },
	});
	// coreTierSize is clamped to the schema-derived candidate cap.
	assert.equal(out.candidateCap, schemaCap);
	assert.equal(out.coreTierSize, schemaCap);
	assert.equal(out.candidateCount, schemaCap);
	assert.equal(
		out.coreCandidates.length + out.tailCandidates.length,
		schemaCap,
	);
	assert.equal(out.capExceeded, true);
	assert.deepEqual(out.droppedCandidateIds, ["claim-049", "claim-050"]);

	// Invalid coreTierSize falls back to the default of 8; fallback ids do not
	// collide with explicit ids.
	const fallback = await helper({
		sources: {
			"sanitize-claims.main": {
				claimInventory: {
					verificationCandidates: [
						{ id: "candidate-001", claim: "Explicit id." },
						{ claim: "Fallback id must not collide." },
					],
				},
			},
		},
		options: { coreTierSize: 0 },
	});
	assert.equal(fallback.coreTierSize, 8);
	assert.deepEqual(
		fallback.coreCandidates.map((candidate) => candidate.id),
		["candidate-001", "candidate-002"],
	);
	assert.deepEqual(fallback.tailCandidates, []);
});

test("deep-review report schema accepts only bounded narrative synthesis", () => {
	const schemaDir = join(
		dirname(fileURLToPath(import.meta.url)),
		"..",
		"..",
		"workflows",
		"deep-review",
		"schemas",
	);
	const reportSchema = parseFixtureJson(
		readFileSync(
			join(schemaDir, "deep-review-report-control.schema.json"),
			"utf8",
		),
	);
	const validControl = {
		schema: "stage-control-v1",
		digest: "concise synthesis",
		summary: "One material issue remains.",
		verdict: "NEEDS_WORK",
		risks: ["One reviewer task was incomplete."],
		recommendedNextAction: "Address the kept findings.",
	};
	const valid = validateJsonSchema(validControl, reportSchema);
	assert.equal(valid.valid, true, JSON.stringify(valid.issues));

	const duplicatedFindings = validateJsonSchema(
		{ ...validControl, findings: [{ findingId: "finding-001" }] },
		reportSchema,
	);
	assert.equal(duplicatedFindings.valid, false);
	assert.ok(
		duplicatedFindings.issues.some((issue) => issue.path === "$.findings"),
	);

	const tooManyRisks = validateJsonSchema(
		{ ...validControl, risks: Array.from({ length: 13 }, () => "risk") },
		reportSchema,
	);
	assert.equal(tooManyRisks.valid, false);
	assert.ok(tooManyRisks.issues.some((issue) => issue.path === "$.risks"));

	const invalidVerdict = validateJsonSchema(
		{ ...validControl, verdict: "block_launch" },
		reportSchema,
	);
	assert.equal(invalidVerdict.valid, false);
	assert.ok(
		invalidVerdict.issues.some((issue) => issue.path === "$.verdict"),
	);
});

